        var batches=new Godot.Collections.Array<Settings>();var reactions=Map(owner,"reactions");reactions.Clear();var configs=new Settings();var authored=new Settings();var exclusions=new Settings();var motions=new Settings();var prototypes=Map(controller,"prototypes");var states=Map(controller,"states");var world=controller.Get("world").As<RefCounted>();foreach(var id in prototypes.Keys){var actor=Actor(controller,id.AsString());var state=states[id].AsGodotDictionary();configs[id]=_settings.sample(actor,controller.Call("_local",actor,time).AsDouble());if(actor.Get("type_id").AsString()=="powder")authored[id]=values(controller,id.AsString(),time);var pose=state["pose"].AsTransform3D();var before=Get(oldPoses,id.AsString(),pose).AsTransform3D();var rotation=(pose.Basis.Orthonormalized().GetRotationQuaternion()*before.Basis.Orthonormalized().GetRotationQuaternion().Inverse()).Normalized();motions[id]=new Settings{["linear"]=(pose.Origin-before.Origin)/(float)Math.Max(.000001,dt),["angular"]=rotation.GetAxis()*(float)(Mathf.Wrap(rotation.GetAngle(),-Mathf.Pi,Mathf.Pi)/Math.Max(.000001,dt))};}
